    }
    const start = i;

    if (isDigit(c) || (c === '.' && isDigit(src[i + 1]))) {
      const p = src[i + 1];
      if (c === '0' && p !== undefined && 'xXbB'.includes(p)) {
        // radix integer: 0x1F, 0b101
        const hex = p === 'x' || p === 'X';
