        }
      }
      push('num', Number(src.slice(i, j)), start);
      i = j;
      continue;
    }

    if (isAlpha(c)) {
      let j = i + 1;
      while (j < n && isAlnum(src[j])) j++;
      push('name', src.slice(i, j), start);
      i = j;
      continue;
    }

    if ('+-*/%^!(),='.includes(c)) {
      push('op', c, start);
      i++;
      continue;
    }

    push('error', `Unexpected character '${c}'`, start);
    return toks;
  }
  push('eof', null, n);
