const toDeg = (rad) => (rad * 180) / Math.PI;

// round half away from zero: round(-2.5) = -3
function roundHalfAway(x) {
  const a = Math.abs(x);
  let r = Math.floor(a);
  if (a - r >= 0.5) r += 1;
  return x < 0 ? -r : r;
